CREATE VIEW [CE].[vwSubscription] AS

	SELECT 
	 [apuk_subscriptionid] AS 'Subscription ID'
	,[apuk_subscriptionnumber] AS 'Subscription Number'
	,[apuk_name]
	,[Product_ID]
	,[Product_Code]
	,[Product_Name]
	,[apuk_paymentmethod]
	,[Payment_Method_Name]
	,[apuk_startdate]
	,[apuk_enddate]
	,[statecode]
	,[State]
	,[statuscode]
	,[Status]
	,[CreatedBy]
	,[Created_By_Name]
	,[createdon]
	,[modifiedon]
	,[ModifiedBy]
	,[Modified_By_Name]
	,[OwnerId]
	,[Owner_Name]
	,[apuk_subscriptionownerid]
	,[apuk_subscriptionowneridname]
	,[apuk_subscriptionownerid_entitytype]
	,[apuk_onbehalfoforganisationid]
	,[apuk_onbehalfoforganisationidname]
	,[apuk_onbehalfoforganisationid_entitytype]
	,[Channel_Code]
	,[Channel]
	,[apuk_allocatedlicenses_date]
	,[apuk_numberoflicenses]
	,[apuk_corporate]
	,[apuk_licensekey]
	FROM [synapse_ce].[vwSubscription]
